### **Code (C++)**

```cpp
class Solution {
    // Helper function for Top-Down DP
    int fn(int i, int currentSum, int& totalSum, vector<int>& nums, vector<vector<int>>& dp) {
        // Base Case: We have processed all elements.
        // currentSum is the sum of Subset A.
        // The remaining elements form Subset B.
        // We return the absolute difference between them using the derived formula.
        if (i == nums.size()) {
            return abs(2 * currentSum - totalSum);
        }

        // Check if this state is already calculated
        if (dp[i][currentSum] != -1) return dp[i][currentSum];

        // Option 1: Skip the current element (It goes to Subset B)
        int skip = fn(i + 1, currentSum, totalSum, nums, dp);

        // Option 2: Take the current element (It goes to Subset A)
        int take = fn(i + 1, currentSum + nums[i], totalSum, nums, dp);

        // Store and return the minimum difference possible from this state
        return dp[i][currentSum] = min(take, skip);
    }

   public:
    int minDifference(vector<int>& arr, int n) {
        int totalSum = 0;
        for (int x : arr) totalSum += x;

        // DP table initialization
        // Rows: n (index), Cols: totalSum + 1 (possible sums)
        vector<vector<int>> dp(n, vector<int>(totalSum + 1, -1));

        return fn(0, 0, totalSum, arr, dp);
    }
};

```

