## Solution
#### Memoization (Top-Down with Early Stopping)
```cpp[]
class Solution{
private:
    bool isSubsetSumPossible(int ind, int target,
                             vector<int>& arr,
                             vector<vector<int>>& memo) {

        if (target == 0) return true;
        if (ind == 0) return target == arr[0];

        if (memo[ind][target] != -1)
            return memo[ind][target];

        bool notTake = isSubsetSumPossible(ind - 1, target, arr, memo);
        bool take = false;

        if (arr[ind] <= target)
            take = isSubsetSumPossible(ind - 1, target - arr[ind], arr, memo);

        return memo[ind][target] = notTake || take;
    }

public:
    int minDifference(vector<int>& arr, int n) {
        int total = 0;
        for (int x : arr) total += x;

        vector<vector<int>> memo(n, vector<int>(total + 1, -1));

        int currentSubsetSum;
        for (currentSubsetSum = total / 2; currentSubsetSum >= 0; currentSubsetSum--) {
            if (isSubsetSumPossible(n - 1, currentSubsetSum, arr, memo))
                break;   // 🔥 EARLY STOP
        }

        return abs((total - currentSubsetSum) - currentSubsetSum);
    }
};
```
#### Tabulation (Bottom-Up with Early Stopping)

```cpp[]
class Solution {
public:
    int minDifference(vector<int>& arr, int n) {
        int total = 0;
        for (int x : arr) total += x;

        vector<vector<bool>> dp(n, vector<bool>(total + 1, false));

        // Base case
        for (int i = 0; i < n; i++)
            dp[i][0] = true;

        if (arr[0] <= total)
            dp[0][arr[0]] = true;

        // Fill DP table
        for (int ind = 1; ind < n; ind++) {
            for (int target = 1; target <= total; target++) {
                bool notTake = dp[ind - 1][target];
                bool take = false;

                if (arr[ind] <= target)
                    take = dp[ind - 1][target - arr[ind]];

                dp[ind][target] = notTake || take;
            }
        }

        // 🔥 Early stopping at S/2
        int currentSubsetSum;
        for (currentSubsetSum = total / 2; currentSubsetSum >= 0; currentSubsetSum--) {
            if (dp[n - 1][currentSubsetSum])
                break;
        }

        return abs((total - currentSubsetSum) - currentSubsetSum);
    }
};
```

